import React, { useEffect, useState } from "react";
import { useParams, useNavigate } from "react-router-dom";

export default function EventPage({ token }) {
  const { id } = useParams();
  const navigate = useNavigate();

  const [event, setEvent] = useState(null);
  const [msg, setMsg] = useState("");

  // Load event
  useEffect(() => {
    fetch(
      (process.env.REACT_APP_API || "http://localhost:4000") +
        "/api/dashboard/events/" +
        id
    )
      .then((r) => {
        if (!r.ok) throw new Error("Not found");
        return r.json();
      })
      .then(setEvent)
      .catch(() => setEvent(null));
  }, [id]);

  // Volunteer button
  async function volunteer() {
    if (!token) {
      navigate("/login");
      return;
    }

    try {
      const res = await fetch(
        (process.env.REACT_APP_API || "http://localhost:4000") +
          "/api/actions/volunteer",
        {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
            Authorization: `Bearer ${token}`,
          },
          body: JSON.stringify({ event_id: id }),
        }
      );

      const d = await res.json();
      setMsg(d.message || "Registered");
    } catch (e) {
      setMsg("Error registering");
    }
  }

  const [ngoDetails, setNgoDetails] = useState(null);
  const [showNgo, setShowNgo] = useState(false);

  async function loadNgo() {
    if (!event || !event.ngo_id) return;
    try{
      const res = await fetch((process.env.REACT_APP_API || 'http://localhost:4000') + '/api/actions/ngo/' + event.ngo_id);
      const d = await res.json(); setNgoDetails(d);
      setShowNgo(true);
    }catch(e){ setShowNgo(false); }
  }

  if (event === null)
    return <div className="event-page">Event not found or loading...</div>;

  return (
    <div className="event-page">
      <h2>{event.title}</h2>

      <img
        src={event.image_url || event.image || "https://via.placeholder.com/900x300"}
        alt={event.title}
        style={{
          width: "100%",
          height: 320,
          objectFit: "cover",
          borderRadius: 8,
        }}
      />

      <p style={{ marginTop: 12 }}>{event.description}</p>

      <div style={{ marginTop: 12 }}>
        <button className="buttons primary" onClick={volunteer}>
          Volunteer / Participate
        </button>

        <button
          className="buttons"
          onClick={() => navigate("/login")}
          style={{ marginLeft: 8 }}
        >
          Login to Participate
        </button>

        <button
          className="buttons"
          onClick={() => navigate("/register")}
          style={{ marginLeft: 8 }}
        >
          Register
        </button>
        {event.ngo_id && (
          <button className="buttons" style={{marginLeft:8}} onClick={loadNgo}>View Hosting NGO</button>
        )}
      </div>

      {msg && (
        <p style={{ marginTop: 12, color: "green" }}>
          {msg}
        </p>
      )}

      {showNgo && ngoDetails && (
        <div style={{marginTop:18,background:'#fff',padding:12,borderRadius:8}}>
          <h4>Hosting NGO</h4>
          <div><strong>{ngoDetails.ngo.name}</strong></div>
          <div style={{fontSize:13,color:'#666'}}>{ngoDetails.ngo.email}</div>
          <div style={{marginTop:8}}>
            <strong>Events</strong>
            {ngoDetails.events.length ? ngoDetails.events.map(ev=>(<div key={ev.id} style={{padding:6}}>{ev.title}</div>)) : <div>No events.</div>}
          </div>
        </div>
      )}
    </div>
  );
}
